// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Why build a custom component for the company API instead of letting each flow call the API with a generic HTTP request component?", "A generic HTTP call puts the URL, headers, auth and parsing into every flow, so each team ends up with its own slightly different copy. A custom component holds that logic once. It has typed inputs, a secret input for the key, one timeout and retry policy, and clear error handling. It returns structured Data or a Message, so downstream components get a stable shape. It can be unit-tested with pytest and loaded from one version-controlled folder, so every flow and Agent runs the same code. You can switch it to tool mode for Agents. A fix or schema update ships in one place instead of being hunted down across dozens of flows."),
    s(5, "How do you make sure an API failure never shows up as an empty success in a flow?", "The output method has to treat every failure path explicitly. I check the status code. A 4xx raises an error that says what was wrong with the request, such as an unknown customer ID or a bad region. A 5xx or timeout raises after the bounded retries run out. I also validate the response body against the fields I expect, and raise if they are missing, so a schema change cannot turn into an empty Data object. I never wrap the call in a broad except that returns an empty list or blank string. The pytest suite has cases for 4xx, 5xx, timeouts and schema changes that assert an exception is raised, so this behaviour cannot regress silently."),
    s(4, "How would you design the timeout and retry policy inside the component?", "Every request gets an explicit timeout, exposed as a typed input with a sensible default, so tweaks can adjust it per request. I retry only failures that are likely to be transient: connection errors, timeouts and selected 5xx or 429 responses. I use a small fixed maximum number of attempts, with exponential backoff and jitter. I never retry 4xx validation errors, because they will fail the same way again. The total time across all attempts has to stay under what the caller can wait, especially for an Agent or a synchronous API request. When retries run out, I raise an error that includes the last status and the attempt count. For write calls, retries also need idempotency keys."),
    s(4, "What exactly would your pytest suite cover, and how do you avoid hitting the real API?", "I instantiate the component class, set its inputs directly, and call the output methods. The HTTP client is mocked, either by patching it or by using a transport-level mock library, so no network call happens and no real key is needed. The cases are: a success that returns correctly shaped Data; a 400 and a 404 with clear messages; a 500 that is retried and then raises; a timeout; a malformed or changed response schema that raises; and a check that the key is sent only in the auth header and never shows up in logs or error text. CI runs this suite before anything is merged into the shared components folder."),
    s(3, "When should the component return Data and when should it return a Message?", "Return Data when downstream components need structured fields, such as a customer record with ID, region, status and balance. Parsers, conditional logic or other components can then read individual keys reliably. Return a Message when the result is going straight into a chat output or a prompt as text, for example a short summary for the user. A component can declare both outputs, each mapped to its own method, so builders pick the shape they need without duplicating API logic. Both methods should share one internal fetch function. That way retries, validation and error handling are identical whichever output a flow connects to."),
    s(4, "How do you roll out a breaking change to a shared component without breaking existing flows?", "Avoid in-place breaking changes. If I need to rename an input, change an output shape or alter semantics, I add a new optional input with a default, or a new output, so existing flows keep working. If the change really cannot be backward compatible, I ship it as a new component class with a clear versioned display name and mark the old one as deprecated in its description. Teams then migrate deliberately. The change goes through code review and CI, merges into the shared folder, and reaches instances when they restart. Tracing tags let me confirm which flows still use the old version before I remove it."),
    s(4, "How could flows still drift onto different copies of the component even with a shared folder, and how do you catch it?", "Drift creeps back in a few ways. A builder edits the component code inside one flow on the canvas. Someone imports a flow exported from another instance that carries older code. Or one Langflow instance was not restarted after the folder changed. To catch it, I treat flows as artifacts too: export the flow JSON into version control, and have CI compare any embedded component code against the shared source. I make sure all instances load the same custom components path from the same commit, and I restart them during rollout. I also discourage inline edits through review. Tracing that records the component version lets me spot runs on unexpected versions in production."),
    s(3, "Give a back-of-envelope estimate of the concurrency this component puts on the company API.", "Little's law is a good starting point: requests in flight equal arrival rate times average latency. As an illustration only, say flows call the component 20 times a second and each API call takes half a second. That is about 10 concurrent requests. Retries multiply this during incidents. With up to three attempts, a failing API can see roughly three times the load, which is why backoff and caps matter. Agents add more uncertainty, because one user question can trigger several tool calls. I would use real numbers from tracing data and the API team's rate limits, then size Langflow workers and any client-side limits from those."),
    s(4, "How do you stop an Agent from hammering the company API with repeated tool calls?", "I use several layers. In the Agent I keep the instructions focused and cap iterations, so it cannot loop forever. In the component, the bounded retries apply on every call, and I can add a simple per-process rate limit or short-lived cache for identical read requests. The tool description tells the model when calling is useful and when it is not, which cuts down speculative calls. Errors are returned as clear messages, so the Agent does not keep retrying a bad customer ID. On the API side, the company gateway should enforce rate limits per caller. Tracing shows tool-call counts per run, so runaway patterns are visible."),
    s(4, "If the component performs a write, such as updating a customer record, how do you keep retries safe?", "Retries are only safe when the operation is idempotent. For writes I generate an idempotency key per logical operation and send it with every attempt, assuming the company API supports one. The API then applies the change once even if a response gets lost and we retry. If the API has no idempotency support, I do not automatically retry non-idempotent calls after a timeout, because the first attempt may have succeeded. Instead I raise a clear error saying the outcome is unknown. For Agents, I would think hard about exposing writes as tools at all, and keep read and write operations as separate components so permissions can differ."),
    s(4, "What makes a good tool description and input description when the component runs in tool mode?", "The Agent decides from text alone, so the descriptions are effectively the API contract for the model. The tool description should say what the tool does, when to use it, and what it returns, for example: looks up a customer's account status by customer ID within a region. Each input description should state the expected format, valid values and constraints, such as the allowed region options. I avoid vague names like data or query. I keep internal details out, especially anything about credentials. Then I test in the Playground with realistic questions to confirm the Agent picks the tool when it should and leaves it alone when it should not."),
    s(5, "How do you prevent the component, used as a tool, from returning data the end user is not allowed to see?", "The model must never be the security boundary. Authorization belongs on the company API side, and the component should pass a caller identity the API can enforce against, not just a shared service key that can read everything. If the flow knows the authenticated user or tenant, that value should come from trusted flow inputs or server-side context, not from arguments the Agent invents. The component can also check that the requested customer ID belongs to the caller's scope before making the call. I also limit returned fields to what the use case needs. Prompt injection can make an Agent ask for anything, so least privilege has to hold at the API."),
    s(4, "Tracing records inputs and outputs. What privacy concerns does that raise and how do you handle them?", "Tracing through Langfuse or LangSmith can capture customer IDs, personal details in responses, and anything else passed between components. I make sure the API key is never an input value that gets traced as plain text. It comes from a global variable through a secret input and is never logged. For personal data, I minimise what the component returns, mask or redact sensitive fields before they hit logs where possible, and check the tracing project's access controls and retention settings. Under Indian data protection rules and company policy, I would also check where the tracing backend stores data and whether self-hosting is needed."),
    s(3, "Which component settings would you allow production callers to override with tweaks, and which would you lock down?", "Tweaks are powerful because they change component settings per request without editing the flow. So I decide deliberately what to rely on. Region and timeout are reasonable per-request overrides, and the component should validate them: region must be one of the dropdown values, and timeout must sit within a sane range. I would not design the flow to depend on callers overriding the API base URL or the credential. If base URL were a configurable input, an untrusted caller could redirect requests and leak data. Keep such values out of inputs, or restrict who can call the flow. Validation inside the component is the real safeguard, because tweaks bypass the canvas."),
    s(3, "What changes when you expose this component to external MCP clients through Langflow's MCP server?", "The audience gets wider. With an internal Agent you control the prompts. With MCP clients, any connected client and its model can discover and call the tool. So the tool and input descriptions must be accurate, and the server must require authentication so only approved clients can connect. The component's own validation and the API's authorization become even more important, because inputs come from systems you do not control. I would expose only read-safe flows at first, keep write operations separate, watch tracing for unexpected call patterns, and make sure error messages stay helpful without leaking internal URLs, stack traces or credential details."),
    s(4, "The company API adds, renames or removes a field. How should the component behave?", "Additive changes should be harmless. The component picks the fields it needs and ignores extras. A renamed or removed required field is a breaking change, and the component should raise a clear schema error naming the missing field rather than return Data with blanks. I validate the response against an explicit expected shape, for example with a small Pydantic model or explicit key checks. The pytest suite includes a changed-schema case to lock this in. Ideally a contract test against the staging API runs regularly too, so we hear about the change before production traffic fails and tracing shows the error spike."),
    s(3, "How would you handle the region dropdown and other input validation in the component?", "A dropdown input constrains the choice on the canvas, but values can still arrive through tweaks, an Agent's tool call or an MCP client. So I validate again inside the output method. Region must be in the allowed list, and the customer ID must match the expected format. Timeout must be a positive number within a ceiling, so nobody sets ten minutes and ties up workers. Invalid values raise an error that names the input and lists the valid options. This is cheap, stops bad requests before they reach the API, and gives an Agent a message it can correct from instead of an opaque 400."),
    s(4, "An API regression appears in production. Walk me through using tracing to find its source.", "First I filter traces for runs where this component failed or got slow, using its name and any version tag the component records. I look at when the change started and line that up with recent merges to the shared folder, instance restarts and the API team's deploys. Then I compare inputs between good and bad runs, checking whether it is one region, a certain timeout tweak, or Agent-generated arguments. Per-component latency shows whether the time is spent in our call or elsewhere in the flow. If one flow is affected and others are not, I check that flow for an outdated embedded copy. Then I reproduce it with a pytest case."),
    s(3, "What are you checking for when you test the component in the Playground?", "Unit tests prove the logic. The Playground proves the builder experience and the integration with real components. I check that the display name, description and icon make sense in the sidebar. Inputs should render with the right types: dropdown options, secret field masked, sensible defaults. I connect the outputs to downstream components to make sure Data and Message shapes work. I trigger error cases deliberately, such as a bad customer ID or a tiny timeout, and confirm the messages are clear and nothing is swallowed. I check the key does not appear anywhere visible. Finally I put the component in tool mode under an Agent and see whether it is chosen correctly."),
    s(4, "How do you rotate the company API key without breaking flows?", "Because the secret input points at a Langflow global variable, no flow holds the key itself. Rotation happens in one place. Ideally the company API supports two valid keys at once. I issue a new key, update the global variable on each instance, confirm through tracing and a test flow that calls succeed, and then revoke the old key. If keys are environment-specific, I rotate dev, staging and production separately. Flows and exports do not change at all. If the key ever leaked, I would revoke it immediately and accept a brief error window, and the component's clear auth error makes that window obvious rather than silent."),
    s(3, "How do you handle dev, staging and production versions of the company API with the same component?", "The component code should be identical across environments. What changes is configuration. Each Langflow instance has its own global variable for the API key and a server-side setting for the base URL, ideally from environment configuration rather than an input any caller could tweak. Every instance loads the same version-controlled components folder, promoted from one commit through dev, staging and then production. Flows are exported and promoted the same way. This keeps behaviour reproducible: a bug in production can be reproduced on staging with the same code, and only the credentials and endpoint differ."),
    s(3, "Should the output method be synchronous or asynchronous, and why does it matter?", "It matters because a blocking network call ties up whatever is executing the flow while it waits. If the server runs work on an event loop, a synchronous HTTP call with a long timeout can stall other runs. Langflow supports async methods on components, so for I/O-bound calls to an API I prefer an async HTTP client with an explicit timeout. That lets the server handle other requests while waiting. The trade-off is that async code is slightly harder to write and test. pytest needs async support, and mocks must be async-aware. Whichever I choose, the timeout and retry caps stay, because async does not make slow calls free."),
    s(3, "Would you cache API responses inside the component? What are the trade-offs?", "Caching helps when the same read is repeated within a short window, for example an Agent looking up the same customer several times in one conversation. A short-lived in-memory cache keyed on customer ID and region cuts latency and API load. The risks are stale data, memory growth, and in a multi-instance deployment each instance having its own inconsistent cache. Data for one caller must never be served to another, so the key needs any identity scope as well. I would never cache errors as successes. For anything where freshness matters, such as balances or statuses, I would skip caching or keep the TTL very short, and document the behaviour in the component description."),
    s(3, "How should error messages differ for a human builder, an Agent and a production API caller?", "All three need honest, specific errors, but the detail differs. Builders in the Playground benefit from the input name, the status code and a hint, such as region must be one of the listed values. An Agent needs a concise message it can act on, such as customer not found, so it can ask the user rather than retry blindly. A production API caller needs a failed run with a stable, recognisable error it can handle or alert on. In every case I exclude secrets, auth headers, full internal URLs and raw stack traces from the message. Full detail goes to tracing and server logs with proper access control."),
    s(2, "Does the custom component need to know about message history or session IDs?", "Usually not. The component should be stateless: given its inputs, it calls the API and returns a result. Chat memory belongs to Langflow's message history, which is keyed by session ID and used by the flow or Agent to keep conversation context. Keeping state out of the component makes it safe to reuse across flows, easy to test, and correct under concurrency, since two sessions never share hidden variables. If the API genuinely needs a conversation or correlation identifier, I pass it as an explicit input. That way it is traceable and testable, rather than read from global state inside the component."),
    s(3, "How would you govern changes to the shared custom components folder?", "Treat it like any shared library. Changes go through pull requests with code owners from the platform team and the API's owning team. CI runs the pytest suite, linting and a check that the component loads. Reviewers look specifically for secret handling, broad exception swallowing, missing timeouts and unreviewed new inputs that could be dangerous through tweaks. Releases are tagged, so instances load a known commit, and rollout follows dev, staging, then production with restarts. A changelog in the description or repository tells builders what changed. That discipline is what actually prevents drift, more than any single tool."),
    s(3, "What happens if a bad commit to the shared folder stops a component from loading at startup, and how do you guard against it?", "Depending on the error, the component may simply be missing from the sidebar, or flows that use it may fail to build. Either way, many teams are affected at once, which is the downside of sharing. Guards: CI imports every component module and instantiates the classes, so syntax errors and bad imports fail the build. Dependencies are pinned and installed in the Langflow image. Rollout is staged, so staging restarts first, and a smoke flow runs against it. Since instances load a tagged commit, rollback is just pointing back to the previous tag and restarting."),
    s(3, "Mocked unit tests pass, but production still breaks. What other testing would you add?", "Mocks only prove the component matches my assumptions about the API. I would add contract tests that call the staging company API on a schedule and in CI before release. They check status codes, response fields and error shapes, so real schema changes surface early. A smoke flow on staging exercises the component end to end through POST /api/v1/run/<flow-id>, including a tweak, to catch integration and loading issues. For Agents, a small set of scripted prompts confirms tool selection still works. Production tracing then acts as the last safety net, with alerts on error rate and latency for this component."),
    s(4, "The company API is down for an hour. How should the component and flows behave, and would you add a circuit breaker?", "The component should fail fast and clearly. Bounded retries with backoff, then a raised error, never empty results. During a long outage, retries from every request only add load and slow down every flow. A simple circuit breaker helps: after repeated failures it short-circuits for a cooldown period and raises an API-unavailable error immediately. In a multi-instance deployment each process has its own breaker state unless it is shared, which is acceptable for this purpose. Flows can then route on the error to tell users the service is unavailable. Tracing alerts tell the team, and the Agent gets a clear message instead of looping."),
    s(2, "Would you build one component with several outputs or several small components for different API endpoints?", "Several outputs on one component work well when they are different views of the same call, such as structured Data and a text Message from the same customer lookup. Each output maps to its own method, sharing one fetch. Separate endpoints with different purposes, especially reads versus writes, are better as separate components. That gives clearer tool descriptions for Agents, narrower inputs and different permissions. A write tool can then be withheld from an Agent while the lookup stays available. The cost is more classes to maintain, so I share the HTTP client, auth and error handling in a common helper module in the same version-controlled folder."),
  ],
  objective: [
    o(5, "Which base class should a Langflow custom component subclass?", ["Langflow's Component base class","A FastAPI router class","A LangSmith tracer class","A pytest fixture class"], 0, "Custom components are Python classes that subclass Langflow's Component base and declare inputs and outputs."),
    o(5, "The company API returns a 500 after all retries. What should the output method do?", ["Return an empty Data object","Return the string \"OK\"","Raise a clear error that includes the status","Retry indefinitely until it succeeds"], 2, "The workflow forbids hiding failures as empty successes, so a clear error is raised once the bounded retries are exhausted."),
    o(5, "How does the component get the API key without it appearing in flow JSON or exports?", ["Hard-code it as a class constant","A secret input pointed at a Langflow global variable","Put it in the component description","Pass it through a tweak on every request"], 1, "A secret input bound to a global variable keeps the key stored encrypted and out of flow JSON and exports."),
    o(4, "Which retry policy is most appropriate for the company API call?", ["Retry every error, including 400s, forever","Never use a timeout so retries are not needed","Retry only on successful responses","Bounded retries with backoff on transient failures such as timeouts and 5xx"], 3, "Only transient failures are worth retrying, and bounded attempts with backoff avoid overloading the API and blocking callers."),
    o(4, "In the unit tests, how should the HTTP calls be handled?", ["Call the production API with the real key","Mock the HTTP client so no network call is made","Skip testing output methods","Test only through the Playground"], 1, "The workflow uses pytest against a mocked HTTP client, covering success, 4xx, 5xx, timeouts and schema changes."),
    o(4, "How does every Langflow instance get the same version of the component?", ["Each builder copies the code into their flow","Email the Python file to teams","Load a version-controlled folder through the custom components path at startup","Paste the code into the Playground each time"], 2, "A version-controlled folder loaded at startup through the custom components path gives every instance the same code."),
    o(4, "What must be done to let the Agent component call the custom component?", ["Switch it to tool mode and give clear input descriptions","Rename it to Agent","Remove all its inputs","Convert it into a webhook"], 0, "The Agent component takes tools, including components switched to tool mode, and picks them using their descriptions."),
    o(4, "Which endpoint do production apps call to run the flow?", ["GET /api/v1/flows/export","POST /api/v1/run/<flow-id>","PUT /api/v1/components/<name>","DELETE /api/v1/run/<flow-id>"], 1, "Flows are run through POST /api/v1/run/<flow-id>, with tweaks available to override component settings."),
    o(3, "The API response is missing a required field after a schema change. What is the best behaviour?", ["Fill the field with an empty string and continue","Return the Data object without the field silently","Raise a schema error that names the missing field","Cache the last good response forever"], 2, "Silently passing incomplete data is a hidden failure. A named schema error surfaces the change immediately."),
    o(3, "Which output type suits a structured customer record that downstream components read by field?", ["Data","A plain print statement","An exception","A log line"], 0, "Data carries structured fields that other components can read reliably, while a Message suits text for chat or prompts."),
    o(3, "Which tracing integrations are named in the workflow for recording component runs and latency?", ["Jaeger and Zipkin only","Langfuse and LangSmith","Prometheus and Grafana only","No tracing is supported"], 1, "The workflow uses Langfuse or LangSmith to record each component run, its inputs and its latency."),
    o(4, "For a write operation that might be retried after a timeout, what keeps retries safe?", ["Increasing the retry count","Removing the timeout","Returning an empty success on timeout","An idempotency key sent with every attempt, if the API supports it"], 3, "An idempotency key lets the API apply the change once even if the request is repeated after a lost response."),
    o(4, "An Agent using the tool could be prompt-injected into requesting another customer's data. Where must authorization be enforced?", ["In the company API, based on a trusted caller identity","In the tool description text","In the Agent's system prompt only","In the component icon"], 0, "The model is not a security boundary. The API must enforce access based on identity it can trust."),
    o(3, "A caller sends a region value through a tweak that is not in the dropdown. What should happen?", ["The dropdown guarantees this cannot happen","The value is ignored and a random region is used","The component validates it and raises an error listing valid regions","The flow is automatically edited"], 2, "Tweaks, Agents and MCP clients can bypass the canvas, so the component must validate inputs itself."),
    o(3, "Which setting is the riskiest to expose as a per-request tweakable input?", ["Timeout within a capped range","The API base URL","Region from an allowed list","Customer ID with format validation"], 1, "An overridable base URL could redirect requests, and possibly credentials, to an attacker-controlled host."),
    o(3, "What does Langflow acting as an MCP server allow?", ["Exposing flows as tools to MCP clients","Encrypting flow JSON exports","Replacing the Playground","Running pytest automatically"], 0, "As an MCP server, Langflow exposes flows as tools that MCP clients can call."),
    o(3, "How does Langflow keep chat memory separate between users?", ["Inside the custom component's class variables","By flow ID only","Through message history keyed by session ID","Through tweaks"], 2, "Message history gives chat memory per session ID, so the component itself can remain stateless."),
    o(3, "Why should the custom component avoid storing per-request data in class or global variables?", ["It makes the icon disappear","Langflow forbids any Python variables","It prevents tool mode","Concurrent sessions could share or overwrite each other's state"], 3, "Hidden shared state breaks correctness under concurrency and makes the component hard to test and reuse."),
    o(4, "A builder edits the component's code inside one flow on the canvas. What risk does this create?", ["None, because all flows share it automatically","That flow drifts onto a different copy of the code","The API key is rotated","Tracing stops working everywhere"], 1, "Inline edits create a local copy that differs from the version-controlled component, which is the drift the workflow forbids."),
    o(3, "Flows call the component at an assumed 20 requests per second, and each call averages 0.5 seconds. Roughly how many calls are in flight?", ["About 10","About 40","About 2","About 0.025"], 0, "By Little's law, in-flight requests equal arrival rate times latency: 20 × 0.5 = 10."),
    o(3, "During an API outage, why do unlimited retries make things worse?", ["They reduce latency","They hide the key","They multiply load on a failing API and tie up flow execution","They improve the success rate"], 2, "Each request retrying keeps hitting the broken API, adding load and slowing every flow that uses the component."),
    o(2, "What does a circuit breaker in the component do after repeated API failures?", ["Deletes the component from the sidebar","Fails fast for a cooldown period instead of calling the API","Returns cached empty results","Switches the flow to a different model"], 1, "A breaker short-circuits calls for a while and raises an immediate clear error, which protects the API and the callers."),
    o(3, "Which should never appear in the component's error messages?", ["The HTTP status code","The name of an invalid input","The list of valid region values","The API key or auth header"], 3, "Error text can reach users, Agents, logs and traces, so secrets must never be included."),
    o(3, "What is the main purpose of running the component in the Playground after unit tests pass?", ["Checking real rendering, connections, outputs and error messages on the canvas","Storing the API key","Replacing version control","Generating the flow ID"], 0, "The Playground validates the builder experience and integration, which mocked unit tests cannot show."),
    o(2, "Each custom component output is connected to its code how?", ["By a tweak at run time","By the component icon","By mapping the output to a method on the class","By the tracing integration"], 2, "Each declared output names a method on the class that produces its value."),
    o(3, "How should a non-backward-compatible change to the shared component usually be shipped?", ["Edit it in place and restart all instances","As a new versioned component, with the old one marked deprecated","By telling builders to edit their flows inline","By changing only the icon"], 1, "A separate versioned component lets teams migrate deliberately and avoids breaking existing flows."),
    o(2, "For a slow, I/O-bound API call, why consider an async output method?", ["It removes the need for timeouts","It encrypts the request","It disables retries","It avoids blocking execution while waiting on the network"], 3, "Async I/O lets the server do other work during the wait, though timeouts and retry caps are still needed."),
    o(3, "Mocked unit tests pass but a real API field was renamed. Which test catches this earliest?", ["A contract test against the staging API","More mocked tests with the old schema","A Playground screenshot","Increasing the timeout"], 0, "Contract tests exercise the real API's responses, so they catch schema changes that mocks cannot reveal."),
    o(2, "Where should the component's read lookup and a write operation live if an Agent should only be allowed to read?", ["In one component with a hidden write flag","In the Agent's prompt","In separate components, giving the Agent only the read tool","In tweaks sent by the Agent"], 2, "Separate components let you give the Agent only safe tools, rather than relying on the model to avoid a write path."),
    o(2, "A short-lived response cache is added to the component. Which rule is essential?", ["Cache errors as empty successes","Never serve one caller's cached data to another unauthorised caller","Use an unlimited TTL for balances","Share the cache key across all regions"], 1, "The cache key must include identity scope, or the cache becomes a data leak between callers."),
  ],
};
export default bank;
